UPDATE "tennis_objectives" SET "block" = 'Slice', "sort_order" = 33, "is_final" = true, "is_active" = true WHERE "ball" = 'naranja' AND "club_id" IS NULL AND "coach_id" IS NULL AND "student_id" IS NULL AND "code" IN ('BN-TEC-SLICE-01');--> statement-breakpoint
-- Resto de aspectos: se mantienen; se numeran detrás de los técnicos (táctico, físico, mental).
UPDATE "tennis_objectives" t SET "sort_order" = r.n FROM (
  SELECT "id", 33 + row_number() OVER (ORDER BY CASE "aspect" WHEN 'tactico' THEN 1 WHEN 'fisico' THEN 2 ELSE 3 END, "block", "sort_order", "code") AS n
  FROM "tennis_objectives" WHERE "ball" = 'naranja' AND "club_id" IS NULL AND "coach_id" IS NULL AND "student_id" IS NULL AND "aspect" <> 'tecnico' AND "is_active"
) r WHERE t."id" = r."id";--> statement-breakpoint

